// Generated from Natural Earth 1:50m admin-0 country boundaries (public domain).
// GeoGuessr uses this Web Mercator map and the same projection for every target.

export const EUROPE_SVG_VIEWBOX = { minX: 0, minY: 0, width: 1000, height: 700 };

const EUROPE_GEO_BOUNDS = Object.freeze({
  minLon: -25,
  maxLon: 75,
  minLat: 32,
  maxLat: 72,
});

const mercatorY = (latitude) => Math.log(Math.tan(
  Math.PI / 4 + Math.max(-85, Math.min(85, Number(latitude) || 0)) * Math.PI / 360
));

export const geoToEuropeSvgCoords = (longitude, latitude) => {
  const top = mercatorY(EUROPE_GEO_BOUNDS.maxLat);
  const bottom = mercatorY(EUROPE_GEO_BOUNDS.minLat);
  return {
    svgX: ((Number(longitude) - EUROPE_GEO_BOUNDS.minLon)
      / (EUROPE_GEO_BOUNDS.maxLon - EUROPE_GEO_BOUNDS.minLon)) * EUROPE_SVG_VIEWBOX.width,
    svgY: ((top - mercatorY(latitude)) / (top - bottom)) * EUROPE_SVG_VIEWBOX.height,
  };
};

export const europeSvgToGeoCoords = (svgX, svgY) => {
  const top = mercatorY(EUROPE_GEO_BOUNDS.maxLat);
  const bottom = mercatorY(EUROPE_GEO_BOUNDS.minLat);
  const longitude = EUROPE_GEO_BOUNDS.minLon
    + (Number(svgX) / EUROPE_SVG_VIEWBOX.width)
      * (EUROPE_GEO_BOUNDS.maxLon - EUROPE_GEO_BOUNDS.minLon);
  const projectedY = top - (Number(svgY) / EUROPE_SVG_VIEWBOX.height) * (top - bottom);
  const latitude = (2 * Math.atan(Math.exp(projectedY)) - Math.PI / 2) * 180 / Math.PI;
  return { longitude, latitude };
};

